test('frame: ball tunnels through brick at high speed (Level 6)', () => {
  const state = createState(6);
  // Speed at level 6 is 710 px/s.
  // dt = 0.05s -> step = 35.5 px.
  // Ball at y = 90, r = 7. Bottom at 97. Brick at 100, h = 20.
  // Next position: y = 90 + 710 * 0.05 = 125.5.
  // Bottom of ball is now at 132.5.
  // Ball was at [83, 97] and is now at [118.5, 132.5].
  // Brick is at [100, 120].
  // The ball's range [97, 132.5] overlaps the brick [100, 120], but only IF we check the whole path.
  // The `collides` function only checks the final position.
  // At y = 125.5, r = 7, ball is [118.5, 132.5].
  // Brick is [100, 120].
  // 125.5 - 7 = 118.5 < 120. 125.5 + 7 = 132.5 > 100.
  // Wait, if the ball is at y=125.5, it still overlaps the brick!
  // Let's make it jump even further.

  state.ball = { x: 100, y: 80, r: 7, vx: 0, vy: 710 }; 
  state.bricks = [{ x: 80, y: 100, w: 40, h: 20, alive: true, points: 10, row: 0 }];

  const dummyCtx = {
    fillStyle: '',
    fillRect: () => {},
    beginPath: () => {},
    arc: () => {},
    fill: () => {},
    fillText: () => {},
  };

  // We simulate one step of physics then one frame of collision.
  // In reality, frame() is called after step().
  // If step(state, 0.05) moves the ball from 80 to 115.5:
  // Ball center y: 80 -> 115.5.
  // Ball bottom: 87 -> 122.5.
  // Brick: [100, 120].
  // At y = 115.5, the ball bottom is 122.5 and top is 108.5.
  // It still overlaps the brick.

  // To truly tunnel, the ball must be completely past the brick.
  // Brick top = 100, bottom = 120.
  // Ball top must be > 120.
  // y - r > 120 => y > 127.
  // y_start + 710 * 0.05 > 127 => y_start + 35.5 > 127 => y_start > 91.5.
  // But if y_start > 91.5, then ball bottom (y_start + 7) > 98.5.
  // If y_start = 93, then ball bottom = 100. It just touches the brick top.
  // Next pos: 93 + 35.5 = 128.5. Ball top = 121.5.
  // The ball has jumped from 100 to 121.5, skipping the brick [100, 120] almost entirely?
  // No, if ball top is 121.5, it's already passed the brick.

  state.ball = { x: 100, y: 93, r: 7, vx: 0, vy: 710 };

  // We simulate the movement that happens in step()
  state.ball.y += state.ball.vy * 0.05; // 93 + 35.5 = 128.5

  frame(dummyCtx, state);

  assert.equal(state.bricks[0].alive, false, 'brick should be broken even if ball jumped over it');
});

