test('frame: ball bounces off brick top face', () => {
  const state = createState(1);
  state.ball = { x: 100, y: 95, r: 7, vx: 0, vy: 100 }; // moving down
  state.bricks = [{ x: 80, y: 100, w: 40, h: 20, alive: true, points: 10, row: 0 }];

  resolveBricks(state);

  assert.ok(state.ball.vy < 0, 'ball should bounce UP after hitting brick top');
});

test('frame: ball bounces off brick bottom face', () => {
  const state = createState(1);
  state.ball = { x: 100, y: 125, r: 7, vx: 0, vy: -100 }; // moving up
  state.bricks = [{ x: 80, y: 100, w: 40, h: 20, alive: true, points: 10, row: 0 }];

  resolveBricks(state);

  assert.ok(state.ball.vy > 0, 'ball should bounce DOWN after hitting brick bottom');
});

test('frame: ball bounces off brick left face', () => {
  const state = createState(1);
  state.ball = { x: 75, y: 110, r: 7, vx: 100, vy: 0 }; // moving right
  state.bricks = [{ x: 80, y: 100, w: 40, h: 20, alive: true, points: 10, row: 0 }];

  resolveBricks(state);

  assert.ok(state.ball.vx < 0, 'ball should bounce LEFT after hitting brick left');
});

test('frame: ball bounces off brick right face', () => {
  const state = createState(1);
  state.ball = { x: 125, y: 110, r: 7, vx: -100, vy: 0 }; // moving left
  state.bricks = [{ x: 80, y: 100, w: 40, h: 20, alive: true, points: 10, row: 0 }];

  resolveBricks(state);

  assert.ok(state.ball.vx > 0, 'ball should bounce RIGHT after hitting brick right');
});

test('frame: ball bounces off brick corner (top-left)', () => {
  const state = createState(1);
  // Ball moving down-right, hitting top-left corner.
  // Penetrations: Top = 95+7-100 = 2, Left = 75+7-80 = 2.
  state.ball = { x: 75, y: 95, r: 7, vx: 100, vy: 100 };
  state.bricks = [{ x: 80, y: 100, w: 40, h: 20, alive: true, points: 10, row: 0 }];

  resolveBricks(state);

  assert.ok(state.ball.vx < 0, 'ball should bounce LEFT after hitting corner');
  assert.ok(state.ball.vy < 0, 'ball should bounce UP after hitting corner');
});

test('frame: ball tunnels through brick at high speed (Level 6)', () => {
  const state = createState(6);
  // Speed at level 6 is 710 px/s.
  // dt = 0.05s -> step = 35.5 px.
  // Ball at y = 93, r = 7. Bottom at 100. Brick at 100, h = 20.
  // Next position: y = 93 + 35.5 = 128.5.
  // Ball top is now 121.5. It is completely below the brick (bottom 120).

  state.ball = { x: 100, y: 93, r: 7, vx: 0, vy: 710 };
  state.bricks = [{ x: 80, y: 100, w: 40, h: 20, alive: true, points: 10, row: 0 }];

  step(state, 0.05);

  assert.equal(state.bricks[0].alive, false, 'brick should be broken even if ball jumped over it');
});

